        { entityType = typeof(BomberBombEntity); return true; }
        if (string.Equals(name, "bomberChest", StringComparison.Ordinal) || string.Equals(name, "BomberChestEntity", StringComparison.Ordinal))
        { entityType = typeof(BomberChestEntity); return true; }
        if (string.Equals(name, "bomberFireZone", StringComparison.Ordinal) || string.Equals(name, "BomberFireZoneEntity", StringComparison.Ordinal))
        { entityType = typeof(BomberFireZoneEntity); return true; }
        if (string.Equals(name, "bomberIceBridge", StringComparison.Ordinal) || string.Equals(name, "BomberIceBridgeEntity", StringComparison.Ordinal))
        { entityType = typeof(BomberIceBridgeEntity); return true; }
        if (string.Equals(name, "bomberParticipant", StringComparison.Ordinal) || string.Equals(name, "BomberParticipantEntity", StringComparison.Ordinal))
        { entityType = typeof(BomberParticipantEntity); return true; }
        if (string.Equals(name, "bomberPickupItem", StringComparison.Ordinal) || string.Equals(name, "BomberPickupItemEntity", StringComparison.Ordinal))
        { entityType = typeof(BomberPickupItemEntity); return true; }
        if (string.Equals(name, "player", StringComparison.Ordinal) || string.Equals(name, "PlayerEntity", StringComparison.Ordinal))
        { entityType = typeof(PlayerEntity); return true; }
        if (string.Equals(name, "world", StringComparison.Ordinal) || string.Equals(name, "WorldEntity", StringComparison.Ordinal))
        { entityType = typeof(WorldEntity); return true; }
        return false;
    }

    /// <inheritdoc />
    public override bool IsEntityType(Type concrete, Type query)
    {
        if (query.IsAssignableFrom(concrete)) return true;
        Type? current = concrete;
        while (current is not null)
        {
            if (current == query) return true;
            current = current.BaseType;
        }
        return false;
    }

